// MCP tools for batch 50 (31-Oct-2026): book-cover sizes for self-publishers and an affinity-diagram board for UX research.
// Pure cores come from src/tools_core50.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/*) — one source of
// truth with /tools/kdp-cover-calculator/, /tools/book-cover-maker/ and /tools/affinity-diagram/. Stateless: no D1/R2, no fetch.
import { MGDBookCover, MGDAffinity } from "./tools_core50.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => (structuredContent ? { content: [{ type: "text", text }], structuredContent } : { content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const PAPERS = ["white", "cream", "color-standard", "color-premium"];

export const TOOL_DEFS = [
  {
    name: "get_book_cover_size",
    description: "Use when a self-published book (Amazon KDP paperback or Kindle eBook) needs its cover size: from trim size, page count and paper/ink returns the full-wrap cover size (back + spine + front + 0.125 in bleed) in inches, mm, points and pixels at any DPI, the spine width, whether spine text is allowed, text safe zones, the barcode box, and an optional true-size SVG template with guides — all from KDP Help formulas (cited). eBook: the recommended 1600 × 2560 px cover. Hardcover wraps are not computed (KDP does not publish the spine formula). Not affiliated with Amazon.",
    inputSchema: {
      type: "object",
      properties: {
        trim: { type: "string", description: "Trim size, e.g. '6x9' (inches), '5.5x8.5', '8.5x11', '152x229mm'. Default 6x9." },
        pages: { type: "integer", minimum: 1, maximum: 1000, description: "Page count of the final interior PDF (paperback). Required for paperback." },
        paper: { type: "string", enum: PAPERS, description: "white = black ink on white paper (default), cream = black ink on cream, color-standard, color-premium." },
        binding: { type: "string", enum: ["paperback", "ebook", "hardcover"], description: "Default paperback. ebook returns Kindle cover pixels; hardcover returns KDP's published wrap rules only." },
        dpi: { type: "integer", minimum: 72, maximum: 1200, description: "Pixels per inch for px values (default 300; KDP's minimum)." },
        direction: { type: "string", enum: ["ltr", "rtl"], description: "Reading direction (rtl swaps front and back panels). Default ltr." },
        svg: { type: "boolean", description: "Include a true-size SVG template with trim, bleed, spine, safe-zone and barcode guides (default false)." },
      },
    },
    annotations: RO("Book cover size (KDP)"),
  },
  {
    name: "make_affinity_diagram",
    description: "Use when user-research notes, interview quotes, survey answers or workshop stickies need to be clustered and shown as an affinity diagram (affinity map): pass groups you have already clustered (JSON, or Markdown with '## Group' headings and '- note' bullets, or CSV with group/note/participant/votes columns), or plain notes with auto_group=true for a deterministic keyword grouping (no AI) to start from. Returns a sticky-note board as SVG, a Markdown summary (themes, note counts, votes, participants) and CSV, plus a link to the free web board where notes can be dragged, voted and exported to PNG/PDF.",
    inputSchema: {
      type: "object",
      properties: {
        groups: { type: "array", items: { type: "object", properties: { name: { type: "string" }, color: { type: "string", description: "yellow, pink, blue, green, orange, purple, teal or grey" }, notes: { type: "array", items: { anyOf: [{ type: "string" }, { type: "object", properties: { text: { type: "string" }, participant: { type: "string" }, votes: { type: "integer" } } }] } } } }, description: "Already-clustered groups (preferred when you have done the synthesis)." },
        notes: { description: "Alternatively raw input: one note per line, CSV/TSV, Markdown (## headings = groups) or a JSON string. Use with auto_group for ungrouped notes.", anyOf: [{ type: "string" }, { type: "array", items: { type: "string" } }] },
        auto_group: { type: "boolean", description: "Group the ungrouped notes by shared keywords (stop words removed, light stemming). Deterministic; review and rename the themes." },
        max_groups: { type: "integer", minimum: 1, maximum: 30, description: "Cap for auto_group (default 8)." },
        title: { type: "string", description: "Board title, e.g. 'Onboarding interviews, Oct 2026'." },
        svg: { type: "boolean", description: "Include the SVG board (default true; false returns just Markdown + CSV)." },
      },
    },
    annotations: RO("Affinity diagram"),
  },
];

// ---- book cover ---------------------------------------------------------------------------------------------------
function bookCover(a) {
  const binding = ["paperback", "ebook", "hardcover"].includes(a.binding) ? a.binding : "paperback";
  const dpi = int(a.dpi, 300, 72, 1200);
  if (binding === "ebook") {
    const e = MGDBookCover.ebook({ dpi });
    return ok(`Kindle eBook cover: ${e.width} × ${e.height} px (height:width ${e.ratio}:1), RGB, JPEG preferred (PNG, non-animated GIF, TIFF accepted), max ${e.maxFileMB} MB, longest side at least ${e.minLongestSide} px and no side over ${e.maxSide} px. Source: KDP Help, Cover Image Guidelines (https://kdp.amazon.com/en_US/help/topic/G6GTK3T3NUHKLEFX). Not affiliated with Amazon.\n\nDesign it in the browser: ${T}/book-cover-maker/`, { ebook: e });
  }
  if (binding === "hardcover") {
    const r = MGDBookCover.hardcoverRules();
    return ok(`Hardcover (case laminate): ${r.note}\n\nPublished rules: wrap ${r.wrap} in, hinge ${r.hinge} in, keep text ${r.safeFromEdge} in from the edges, barcode ${r.barcode.join(" × ")} in placed ${r.barcodeFromBottom} in from the bottom and ${r.barcodeFromHinge} in from the hinge; ${r.pages[0]}–${r.pages[1]} pages. Source: ${r.source}\n\nFor paperbacks call get_book_cover_size(binding="paperback", trim, pages, paper).`, { hardcover: r });
  }
  if (a.pages == null) return err("Pass pages (the interior page count) for a paperback cover, plus trim (e.g. '6x9') and paper (white, cream, color-standard, color-premium).");
  const opts = { trim: str(a.trim, 40) || "6x9", pages: Number(a.pages), paper: PAPERS.includes(a.paper) ? a.paper : "white", binding: "paperback", dpi, direction: a.direction === "rtl" ? "rtl" : "ltr" };
  const res = MGDBookCover.compute(opts);
  if (!res.ok) return err(`Cannot size this cover: ${res.errors.map((e) => e.message).join(" ")}${res.warnings.length ? " (" + res.warnings.map((w) => w.message).join(" ") + ")" : ""}`);
  const s = res.size, sp = res.spec, R = res.rects;
  const lines = [
    `**${sp.trim.name} paperback, ${sp.pages} pages, ${sp.paperLabel.toLowerCase()}** (${sp.inchesPerPage} in per page):`,
    `| | inches | mm | points | px @ ${dpi} DPI |\n|---|---|---|---|---|\n` +
      [["Full cover (with bleed)", s.width, s.height], ["Spine", s.spine, s.height], ["Trim (one panel)", s.trimWidth, s.trimHeight]]
        .map(([n, w, h]) => `| ${n} | ${w.in} × ${h.in} | ${w.mm} × ${h.mm} | ${w.pt} × ${h.pt} | ${w.px} × ${h.px} |`).join("\n"),
    `Bleed ${s.bleed.in} in on the top, bottom and outside edges. Panels, measured from the left edge in inches: ` + ["back", "spine", "front"].sort((p, q) => R[p].x - R[q].x).map((k) => `${k} ${R[k].x}–${+(R[k].x + R[k].w).toFixed(6)}`).join(", ") + ".",
    `Spine text: ${res.spineText.allowed ? `allowed (keep ${res.spineText.gapEachSide.in} in clear each side; usable spine ${res.spineText.safeWidth.in} in)` : `not allowed below ${res.spineText.minPages} pages`}. Keep front/back text ${res.rules.textInset} in inside the trim; minimum ${res.rules.minTextPt} pt text; images ≥ ${res.rules.minDpi} DPI.`,
    `Barcode: ${res.rules.barcode.w} × ${res.rules.barcode.h} in white box, ${res.rules.barcode.fromSpineAndTrim} in from the spine and bottom trim on the back cover (box at x ${R.barcode.x}, y ${R.barcode.y} in).`,
  ];
  if (res.warnings.length) lines.push("Notes: " + res.warnings.map((w) => w.message).join(" "));
  const svg = a.svg ? MGDBookCover.svgTemplate(res) : null;
  if (svg) lines.push("True-size template (1 unit = 1 pt):\n" + fence("svg", svg));
  lines.push(`Sources (KDP Help): ${res.sources.join(" ")}. Not affiliated with Amazon.\nTemplate PDF/PNG: ${T}/kdp-cover-calculator/#${MGDBookCover.toHash(opts)} · design the cover: ${T}/book-cover-maker/#${MGDBookCover.toHash(opts)}`);
  return ok(lines.join("\n\n"), { spec: sp, size: s, rects_in: R, rects_px: res.rectsPx, spine_text: res.spineText, rules: res.rules, warnings: res.warnings, svg, sources: res.sources });
}

// ---- affinity diagram ---------------------------------------------------------------------------------------------
function affinity(a) {
  let model;
  const title = str(a.title, 120);
  if (Array.isArray(a.groups) && a.groups.length) {
    model = MGDAffinity.parse({ title, groups: a.groups.slice(0, 60) });
  } else if (a.notes != null && (Array.isArray(a.notes) ? a.notes.length : str(a.notes, 1).trim())) {
    const raw = Array.isArray(a.notes) ? a.notes.slice(0, 2000).map((n) => str(n, 600).replace(/\n+/g, " ")).join("\n") : str(a.notes, 300000);
    try { model = MGDAffinity.parse(raw, { title }); } catch (e) { return err("Could not read notes: " + str(e && e.message, 200) + ". Pass one note per line, CSV, Markdown (## Group / - note) or groups[]."); }
  } else return err("Pass groups (already clustered: [{name, notes:[...]}]) or notes (one per line, CSV or Markdown) — add auto_group=true to group raw notes by shared keywords.");
  if (title) model.title = title;
  if (a.auto_group) model = MGDAffinity.applyAutoGroup(model, { maxGroups: int(a.max_groups, 8, 1, 30) });
  const st = MGDAffinity.stats(model);
  if (!st.notes) return err("No notes found in the input.");
  const md = MGDAffinity.toMarkdown(model), csv = MGDAffinity.toCSV(model);
  const svg = a.svg === false ? null : MGDAffinity.toSVG(model);
  const parts = [`Affinity diagram${model.title ? " — " + model.title : ""}: ${st.notes} note(s) in ${st.groups} group(s)${st.ungrouped ? `, ${st.ungrouped} ungrouped` : ""}${st.votes ? `, ${st.votes} vote(s)` : ""}${st.participants ? `, ${st.participants} participant(s)` : ""}.${a.auto_group ? " Groups came from shared keywords (no AI): rename them as themes and move stray notes." : ""}`, md];
  if (svg) parts.push("Board (SVG):\n" + fence("svg", svg));
  parts.push(`Drag notes, dot-vote and export PNG/PDF in the browser: ${T}/affinity-diagram/ (paste the Markdown above).`);
  return ok(parts.join("\n\n"), { title: model.title || "", stats: st, groups: model.groups.map((g) => ({ name: g.name, color: g.color, ungrouped: g.id === MGDAffinity.UNGROUPED, notes: g.notes.map((n) => ({ text: n.text, participant: n.participant || "", votes: n.votes })) })), markdown: md, csv, svg });
}

// ---------------------------------------------------------------------------------------------------------------------
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools50Tool(name) { return NAMES.has(name); }

export async function callTools50Tool(name, a) {
  a = a || {};
  try {
    if (name === "get_book_cover_size") return bookCover(a);
    if (name === "make_affinity_diagram") return affinity(a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}

export const NEXT50 = {
  get_book_cover_size: "Next step: search_design_inspiration(query='book cover') or search_museum_art for cover imagery (public domain); generate_color_combinations for a cover palette.",
  make_affinity_diagram: "Next step: turn the strongest themes into a persona or journey (https://madegooddesigns.com/tools/user-persona-template/), or a design brief with generate_design_md once direction is set.",
};
